import json
from pathlib import Path
O=Path(__file__).resolve().parent
S={k:json.load(open(O/(k+'_silhouette_report.json')))for k in ['C23','C25_v1','C25_v2']};G={k:json.load(open(O/(k+'_geometry_report.json')))for k in ['C25_v1','C25_v2']};C={k:json.load(open(O/(k+'_comparison.json')))for k in ['C25_v1','C25_v2']}
rows=[]
for category in ['panel_branches','support_branches']:
 maps={k:{b['id']:b for b in r[category]}for k,r in S.items()}
 for bid,b in maps['C23'].items():
  rows.append({'id':bid,'category':category,'source_points':b['source_annotation']['points_xy'],'source_tolerance_px':b['tolerance_px'],'versions':{k:maps[k][bid]['visible_metrics']for k in maps}})
comp={'id':'H_C_L_RETURN_OUTER_FIXED_COMPOSITE','tolerance_px':3,'ownership':'C23 first six observations panel and last two support; v1/v2 all eight frame/support. Fixed declared ownership, never best-any-object.','versions':{'C23':C['C25_v1']['fixed_composite_return']['C23'],'C25_v1':C['C25_v1']['fixed_composite_return']['C25_v1'],'C25_v2':C['C25_v2']['fixed_composite_return']['C25_v2']}}
R={'status':'BOUNDED_ITERATION_COMPLETE_SOURCE_UNACCEPTED','rows':rows,'fixed_composite_return':comp,'versions':{k:{'geometry_status':C[k]['status'],'model_sha256':S[k]['sha256_before'],'shared_scene_invariance_pass':G[k]['invariance']['pass'],'white_match':C[k]['white_material_invariance']['status'],'nonchair_collisions':C[k]['fullscene_nonchair_contacts'],'panel_foot_visibility_verified_count':sum(b['nearest_visible_foot_verified_count']for b in S[k]['panel_branches'])}for k in C},'scope':'Source/C23/v1/v2 fixed native-coordinate source observations and unchanged tolerances. Native rendered appearance is reviewed separately. No model or camera modifications by reviewer.'};(O/'C25_bounded_iteration_comparison.json').write_text(json.dumps(R,ensure_ascii=False,indent=2))
lines=['# Source / C23 / C25 v1 / C25 v2: bounded independent comparison','','Final status: source-unaccepted. V1 passes the tested numerical geometry checks. V2 additionally fails numerical geometry cleanup because the left-frame object has 24 components (one main solid, 23 tiny remnants) and two degenerate triangles. Neither version adds detected room/sofa collisions.','','Both material/white pairs match geometrically and retain all 35 cameras, transforms and visibility. Both retain all C23 scene state except the declared panel and left-support mesh changes.','','## Native source errors','','RMS / maximum in pixels, followed by scored/original record count. Panel errors are restricted to the named physical branch; support errors are directed x-at-original-y. Missing points remain failures.','','| Source branch | Source tolerance/count | C23 | C25 v1 | C25 v2 |','|---|---:|---:|---:|---:|']
def fmt(m):
 n=m.get('record_count',m.get('original_source_count'));return f"{m['rms_px']:.3f} / {m['max_px']:.3f} ({m['scored_count']}/{n})"if m['rms_px']is not None else f"missing (0/{n})"
for r in rows:lines.append('| '+r['id']+' | '+str(r['source_tolerance_px'])+' px / '+str(len(r['source_points']))+' | '+' | '.join(fmt(r['versions'][k])for k in S)+' |')
lines+=['','## Composite return with fixed ownership','','The per-object C23 return score above covers only two visible records. For a comparable whole-chair return score, C23 uses the panel for the first six source records (y=906–1020) and the post for the last two (1048/1070); both C25 versions use the left-frame/post object for all eight. This ledger is declared construction attribution, not source-proven ownership and not error-minimizing object selection.','','| Composite source | C23 | C25 v1 | C25 v2 |','|---|---:|---:|---:|','| H return, 8 original points | '+' | '.join(fmt(comp['versions'][k])for k in S)+' |','','V2 has no directed frame boundary at source (440,906), so its 7-point RMS/max must not be treated as an all-eight-point pass. Of the eight original records, C23 has 2 within 3 px, v1 has 3, and v2 has 6; both the missing v2 point and its 3.171 px point fail.','','## Verification limits','','- Numerical closedness, orientation and BVH checks are not exact rational certification. Adjacent triangles sharing a mesh vertex are excluded from self-intersection checks.','- Separate chair objects overlap at intended joints; these are not one welded physical object.','- Full-scene contact scans test 678 non-chair pairs in each model, including hidden geometry; containment uses bounded three-direction ray-parity samples.','- All 49 nearest panel feet in v1 and v2 pass geometric full-scene visibility probes. Material alpha/transmission and absent person/foreground occluders are not simulated.','- G and 665 are prior training/regression views, not held-out evidence.','- The remaining visual structural mismatches are not overruled by numerical results.']
(O/'C25_bounded_iteration_comparison.md').write_text('\n'.join(lines)+'\n');print(json.dumps(R['versions'],ensure_ascii=False,indent=2))
